__NUXT_JSONP__("/tw/price", (function(a,b,c,d,e,f,g,h,i,j,k,l,m){return {data:[{details:{slug:c,pageTitle:"價格 | Mentor Language Institute",pageDescription:"若是您已經有自己的住宿選擇，您不需要支付②住宿費用。",title:"價格",image:"\u002Fimages\u002Fprices\u002Fprice\u002Fget-a-quote.jpg",button:{lists:[{link:["\u003Ca class=\"btn btn-primary\" href=\"\u002Ftw\u002Fprice-auto\"\u003E價格計算機\u003C\u002Fa\u003E"]}]},steps:{title:"①學費＋ ②住宿費用＋ ③其它費用",subtitle:["若是您已經有自己的住宿選擇，您不需要支付②住宿費用。\u003Cbr\u003E*Please use \u003Ca href=\"\u002Ftw\u002Fprice-auto\u002F\"\u003Ethe price calculator\u003C\u002Fa\u003E to get a quote."],lists:[{title:"①學費",subtitle:["費用將根據您的課程及您住宿的時間有所不同。您在MLI上課越久，越多折扣。"],image:"\u002Fimages\u002Fprices\u002Fprice\u002FPRICE_CHART_WEB_JAN06.jpg",link:["\u003Cb\u003E問與答\u003C\u002Fb\u003E","\u003Cb\u003E問題1: 我可以用信用卡付款嗎？ \u003C\u002Fb\u003E\u003Cbr \u002F\u003E\u003Cb\u003E答案1:\u003C\u002Fb\u003E 可以，您可以使用信用卡付款，但會加收 4% 的手續費。","\u003Cb\u003E問題2：我可以使用哪些方式向 MLI 付款？\u003C\u002Fb\u003E \u003Cbr \u002F\u003E\u003Cb\u003E答案2：\u003C\u002Fb\u003E 我們接受以下付款方式： \u003Cbr\u003E • 銀行轉帳 \u003Cbr\u003E • 國際匯款 \u003Cbr\u003E • 現金 \u003Cbr\u003E • 個人支票 \u003Cbr\u003E • 信用卡 \u003Cbr\u003E • 借記卡 \u003Cbr\u003E • Zelle","如果您希望避免信用卡\u002F簽帳卡支付所產生的4%服務費，您可以選擇以下替代方式：\u003Cbr\u003E\u003Cb\u003E銀行轉帳、國際電匯（須支付35美元銀行手續費）、現金、個人支票或 Zelle。\u003C\u002Fb\u003E","\u003Cb\u003E問題3: 我可以在課程開始後再支付學費嗎？ \u003C\u002Fb\u003E\u003Cbr \u002F\u003E\u003Cb\u003E答案3:\u003C\u002Fb\u003E 不可以。必須在課程開始前或第一天前完成全額付款。"],category:[{title:"可選服務",table:{tableMaxCol:d,title_optional:"身份變更（如果您持有 B1\u002FB2 或 J1 簽證並且目前在美國）或恢復",tbody:[["\u003Cb\u003E費用說明\u003C\u002Fb\u003E","\u003Cb\u003E申請人類型\u003C\u002Fb\u003E","\u003Cb\u003E費用\u003C\u002Fb\u003E","\u003Cb\u003E申請人數\u003C\u002Fb\u003E"],["$1,885 服務費，包括填寫費 ($370) 及郵寄費 \u003Cbr\u003E *批准後，600 美元將作為學生的學費抵免（非現金價值）。","F1學生簽證","1,885 美元","1"],["每位受扶養人 365 美元服務費","F2家屬簽證","365 美元",b]]}}]},{title:"②住宿費用",subtitle:["我們提供學生寄宿家庭及宿舍兩個選擇。寄宿家庭推薦給那些想體驗美國文化的人。宿舍推薦給那些想結交很多朋友的人。"],category:[{title:"寄宿家庭金額",table:{tableMaxCol:3,title:"安置費用* : $300\u003Cbr \u002F\u003E 如果未滿 18 歲，租金將比 18 歲以上的人高出約 10%。",thead:[b,e,"合住***"],tbody:[[f,a,a],[g,"$436","$384"],[h,"$872","$768"],[i,"$1,308","$1,152"],[j,"$1,744","$1,536"],[k,"$3,160","$2,904"],[l,"$4,740","$4,356"]]}},{title:"宿舍費用",table:{tableMaxCol:d,title:"安置費用* : $200\u003Cbr \u002F\u003E 如果未滿 18 歲，租金將比 18 歲以上的人高出約 10%。",thead:[b,e,"合住","合住(四人)"],tbody:[[f,a,a,a],[g,"$570","$430","$315"],[h,"$1,140","$860","$630"],[i,"$1,710","$1,290","$945"],[j,"$2,280","$1,720","$1,260"],[k,"$4,320","$3,080","$2,320"],[l,"$6,480","$4,620","$3,480"]]},description:["*安置費用需一次性繳交。不可退還。\u003Cbr \u002F\u003E**保證金將在學生搬出後退還。\u003Cbr \u002F\u003E***您如果申請寄宿家庭的合住房間，您需要和另一個人一起申請。","※您的住宿將由 U.S. Support Service Inc.或是其它仲介提供。","\u003Ca href=\"\u002Ftw\u002Fstay\u002F\"\u003E\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E  關於住宿更多的資訊\u003C\u002Fa\u003E"]}]},{title:"③其它費用",subtitle:["除了上述的費用，還有其它最初的費用。"],lists:["最初處理費用* ： $150","I-20 郵寄費用** : $120","SEVIS 費用** ： $350 (直接向 SEVP付款)","教科書 ： $150-240"],description:["*不可退還\u003Cbr \u002F\u003E**如果使用學生簽證"]}]},examples:{title:"舉例",subtitle:["費用舉例 : 1個月 (4周) 及一年 (48周)"],lists:[{title:"1個月 (4周)",items:[m,"學費 : $1,220","住宿 : $1,630（Dormitory : Quad Rent + Placement Fee + Airport Pickup- oneway)","\u003Cspan class='total'\u003E總額 : $3,000\u003C\u002Fspan\u003E"]},{title:"一年 (48周)",items:[m,"學費 : $10,032","住宿 : $13,810（Dormitory : Quad Rent + Placement Fee + Airport Pickup- oneway)","\u003Cspan class='total'\u003E總額 : $23,992\u003C\u002Fspan\u003E"]}]},other_info:["若是您有任何關於費用的問題，歡迎聯繫我們。"],dir:"\u002Fprice",path:"\u002Fprice\u002Ftw",extension:".json",createdAt:"2026-10-22T16:31:30.211Z",updatedAt:"2026-03-24T13:34:16.715Z"},lang:c}],fetch:{},mutations:void 0}}("$300","","tw",4,"私人","\u003Cb\u003E保證金**\u003C\u002Fb\u003E","1週","2週","3週","4週","8週","12週","入學費用 : $150")));